insert into public.livro_inimigos(id, nome, elemento, vd, pagina, dados) values
(1,'Anjo','Conhecimento','380',234,'{"tamanho": "Enorme", "pv": 1111, "desloc": 24.0, "atr": {"agi": 4, "for": 5, "int": 5, "pre": 5, "vig": 5}, "fort": 25, "refl": 25, "vont": 30, "ini": 25, "perc": 25, "pericias": [], "resist": "Dano 50", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Asas do Conhecimento", "alc": "Corpo a corpo x2", "teste": 40, "dano": "4d10+40 Conhecimento"}, {"n": "Olhares do Saber", "alc": "Distância x2 Longo", "teste": 40, "dano": "6d8+20 Conhecimento"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 10d6 mental"}, {"n": "Julgamento", "acao": "Passiva", "desc": "O anjo é uma criatura que se manifesta como fisicalização do Conhecimento e, portanto, é uma criatura que julga o saber. Sempre que um ser sofre dano de Conhecimento das asas do Conhecimento ou dos olhares do saber do Anjo, sofre também uma quantidade de dano mental igual à metade do dano de Conhecimento sofrido (após aplicar resistências). Um ser reduzido a Sanidade 0 desta forma tem sua mente colapsada pelo julgamento do Anjo e inexiste, morrendo instantaneamente."}, {"n": "Faixas Detentoras", "acao": "Livre", "desc": "Se o anjo acertar um ataque de asas do Conhecimento em um ser Médio ou menor, pode tentar agarrar o alvo (teste 5 O +45) usando as faixas que prendem suas asas. Um ser agarrado desta forma também fica fascinado. O anjo pode manter um ser agarrado desta forma por vez e fazer isso não impede que ele use suas asas do Conhecimento."}, {"n": "Chamas Reveladoras", "acao": "Padrão", "desc": "O anjo manifesta um círculo de chamas douradas em volta de si, que se expande em alcance médio. Todos os seres nesta área sofrem 10d8 pontos de dano de Conhecimento (Vontade DT 43 reduz à metade). Um ser que sofra dano dessa habilidade fica com uma auréola reveladora em cima de sua cabeça. Até o final da cena, o anjo sabe exatamente onde estão todos os seres com auréola, o que significa que ele ignora furtividade e qualquer tipo de invisibilidade ou efeito ilusório."}, {"n": "Raio Dourado", "acao": "Completa", "desc": "Uma vez por cena, o anjo dispara um raio dourado de seu olho central. Todos os seres em uma linha de 3m em alcance longo sofrem 15d8+50 pontos de dano de Conhecimento (Reflexos DT 43 reduz à metade)."}], "desc": "", "def": 57}'::jsonb),
(2,'Bicho-papão','Conhecimento','300',237,'{"tamanho": "Grande", "pv": 750, "desloc": 15.0, "atr": {"agi": 5, "for": 4, "int": 3, "pre": 5, "vig": 4}, "fort": 15, "refl": 25, "vont": 20, "ini": 20, "perc": 20, "pericias": [{"n": "Atletismo", "b": 15}, {"n": "Furtividade", "b": 18}], "resist": "Balístico, corte, impacto e Conhecimento 20", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garras Atormentadoras", "alc": "Corpo a corpo x3", "teste": 35, "dano": "4d10+10 Conhecimento"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 7d8 mental NEX 90%+ é imune"}, {"n": "Tamanho Adaptável", "acao": "Passiva", "desc": "O bicho-papão consegue se esconder em locais menores que ele, reduzindo seu corpo para qualquer categoria de tamanho menor de maneira paranormal. Além disso, seu deslocamento não é reduzido por andar furtivamente ou escalar."}, {"n": "Tormento Infantil", "acao": "Passiva", "desc": "O bicho-papão fica desprevenido se estiver ouvindo uma cantiga de ninar ou outra canção infantil. Além disso, se estiver ouvindo o choro de uma criança, ele usará todas as suas ações disponíveis para encontrar e silenciar a fonte do choro."}, {"n": "Destruir Mente", "acao": "Passiva", "desc": "O bicho-papão destrói e devora a mente assustada de seus alvos. Sempre que acerta um alvo perturbado com suas garras atormentadoras, o bicho-papão causa também 1d8 pontos de dano mental por acerto."}, {"n": "Atormentar", "acao": "Movimento", "desc": "O bicho-papão envia sussurros e perturbações para um ser em alcance curto. O alvo sofre 3d8 pontos de dano mental (Vontade DT 30 reduz à metade). Caso o bicho-papão esteja escondido do alvo, este dano aumenta em +3d8."}, {"n": "Saltar e Assustar", "acao": "Completa", "desc": "Se estiver escondido de um ser em alcance curto, o bicho-papão pode sair do esconderijo e se aproximar deste ser. Enquanto faz isso, seu corpo aumenta e se retorce, assumindo uma forma assustadora. O ser do qual o bichopapão estava escondido sofre 10d8 pontos de dano mental (Vontade DT 35 reduz à metade)."}], "desc": "", "def": 41}'::jsonb),
(3,'Espreitador','Conhecimento','220',238,'{"tamanho": "Médio", "pv": 500, "desloc": 12.0, "atr": {"agi": 4, "for": 2, "int": 3, "pre": 3, "vig": 2}, "fort": 10, "refl": 15, "vont": 15, "ini": 15, "perc": 15, "pericias": [{"n": "Furtividade", "b": 20}], "resist": "Imune: Dano", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo x2", "teste": 10, "dano": "1d6+2 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 30 7d6 mental NEX 70%+ é imune"}, {"n": "Correr Pelas Frestas", "acao": "Movimento", "desc": "O espreitador pode se teletransportar para qualquer espaço em alcance longo, desde que exista uma pequena fresta em seu caminho (uma fresta é um espaço Pequeno ou menor, completamente delimitado por outro objeto ou superfície, como a fresta de porta entreaberta ou um pequeno buraco que atravessa uma parede)."}, {"n": "Espreitar", "acao": "Completa", "desc": "Uma vez por cena, se estiver adjacente a um ser que esteja dormindo, o espreitador causa 10d6 pontos de dano mental neste ser (Vontade DT 30 reduz à metade). Se a vítima ficar enlouquecendo devido a este dano, o espreitador pode criar uma cópia observada dela."}, {"n": "Cópia Observada", "acao": "Padrão", "desc": "O espreitador manifesta uma cópia de um ser que tenha deixado enlouquecendo com sua habilidade Espreitar. A cópia utiliza a mesma ficha do ser, mas causa dano de Conhecimento em vez de seu dano normal, não pode conjurar rituais ou usar habilidades paranormais e dura até o fim da cena."}], "desc": "", "def": 34}'::jsonb),
(4,'Estrangeiro','Conhecimento','340',241,'{"tamanho": "Grande", "pv": 750, "desloc": 15.0, "atr": {"agi": 3, "for": 5, "int": 5, "pre": 5, "vig": 3}, "fort": 15, "refl": 20, "vont": 25, "ini": 20, "perc": 25, "pericias": [{"n": "Ciências", "b": 20}, {"n": "Ocultismo", "b": 20}, {"n": "Furtividade", "b": 20}], "resist": "Imune: Dano", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Toque Sutil", "alc": "Corpo a corpo x3", "teste": 35, "dano": "4d8+10 Conhecimento"}, {"n": "Rajada Psíquica", "alc": "Distância x2 EXTREMO", "teste": 35, "dano": "4d10+20 Conhecimento"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 10d6 mental NEX 99%+ é imune"}, {"n": "Comandar", "acao": "Livre", "desc": "O é capaz de comandar mentalmente seres com mente inferior à sua. Sempre que causa dano em um ser com sua rajada psíquica, o pode dominar a mente do alvo. O alvo deve passar em um teste de Vontade (DT 35) ou será forçado a cumprir uma ordem do , entre as opções a seguir, emitida como parte desta ação. O ser obedece a ordem em seu próximo turno. Seres com Intelecto 5 ou mais são imunes a essa habilidade. Atacar. O ser ataca um aliado com a arma que tem em mãos, mas não gasta PE nesse ataque. Render-se. O ser cai no chão e arremessa suas armas em uma direção aleatória em alcance curto. Fugir. O ser se afasta do da maneira mais eficiente possível."}, {"n": "Apagar Memória", "acao": "Livre", "desc": "Um ser que fique insano por conta dos ataques e efeitos do tem consequências diferentes do habitual. A vítima tem a mente completamente controlada pelo , que passa a controlar as ações do personagem. Como alternativa, o pode apagar a memória da vítima e devolver um pouco de Sanidade (1d4) a ela, fazendo-a duvidar da existência do e de seu encontro com esta criatura."}, {"n": "Oblívio", "acao": "Livre", "desc": "Um ser que sofra dano do Toque Sutil esquece momentaneamente a existência do (Vontade DT 30 evita). A vítima considera o invisível e esquece qualquer interação que teve com ele. No final de cada um de seus turnos, o ser deve repetir o teste de Vontade. Se passar, volta a perceber a presença da criatura e encerra este efeito, mas sofre 6d6 pontos de dano mental. Uma vítima que esteja incubando uma larva de (veja Incubar) não tem direito a repetir o teste de Vontade no final de seus turnos."}, {"n": "Incubar", "acao": "Completa", "desc": "O toca um ser adjacente e que esteja alheio a sua presença (veja Oblívio) e coloca uma larva dentro dele. Enquanto o ser estiver incubando uma larva, o tem total acesso a sua mente, lendo pensamentos e memórias dele, mesmo à distância. A larva consome a Sanidade do hospedeiro, causando 1d6 pontos de dano mental no início de cada cena. Quando a Sanidade do hospedeiro é reduzida a 0, um novo eclode de sua cabeça, matando-o instantaneamente. 224411"}], "desc": "", "def": 50}'::jsonb),
(5,'Existido','Conhecimento','20',242,'{"tamanho": "Médio", "pv": 36, "desloc": 9.0, "atr": {"agi": 1, "for": 1, "int": 4, "pre": 2, "vig": 2}, "fort": 0, "refl": 0, "vont": 10, "ini": 5, "perc": 5, "pericias": [{"n": "Ciências", "b": 10}, {"n": "Ocultismo", "b": 10}], "resist": "Balístico, corte e impacto 5, Conhecimento 10", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo", "teste": 5, "dano": "1d4+1 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 14 1d6 mental NEX 25%+ é imune"}, {"n": "Brilho Enlouquecedor", "acao": "Livre", "desc": "Uma vez por rodada, o existido faz suas marcas douradas brilharem. Todos os seres em alcance médio capazes de vê-lo sofrem 1d6 pontos de dano mental (Vontade DT 14 reduz à metade). MOVIMENTO"}, {"n": "Fortalecimento Paranormal", "acao": "Livre", "desc": "Até o fim da cena, o existido recebe + O em todos os testes baseados em Agilidade, Força e Vigor e suas pancadas causam +2d4 pontos de dano de Conhecimento. O existido só pode usar esta habilidade se tiver causado dano mental a algum personagem com seu Brilho Enlouquecedor nesta cena. 242 Existido"}], "desc": "", "def": 13}'::jsonb),
(6,'Lembrado','Conhecimento','100',243,'{"tamanho": "Médio", "pv": 180, "desloc": 9.0, "atr": {"agi": 2, "for": 2, "int": 4, "pre": 2, "vig": 2}, "fort": 5, "refl": 0, "vont": 10, "ini": 10, "perc": 10, "pericias": [{"n": "Ciências", "b": 10}, {"n": "Ocultismo", "b": 10}], "resist": "Balístico, corte e impacto 10, Conhecimento 20", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo x2", "teste": 5, "dano": "2d4+7 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 4d6 mental NEX 45%+ é imune"}, {"n": "Aura Manifestada", "acao": "Passiva", "desc": "O lembrado é cercado por uma aura dourada de faces flutuantes, que gritam com todos aqueles que se aproximam. Personagens em alcance curto do lembrado sofrem – OO em todos os testes."}, {"n": "Expandir Aura", "acao": "Padrão", "desc": "O lembrado expande sua aura. Seres em alcance curto sofrem 6d6 pontos de dano mental (Vontade DT 20 reduz à metade)."}], "desc": "", "def": 22}'::jsonb),
(7,'Máscara do Desespero','Conhecimento','400',254,'{"tamanho": "Minúsculo", "pv": 1200, "desloc": 12.0, "atr": {"agi": 4, "for": 4, "int": 6, "pre": 6, "vig": 5}, "fort": 35, "refl": 25, "vont": 35, "ini": 25, "perc": 35, "pericias": [{"n": "Ciências", "b": 35}, {"n": "Ocultismo", "b": 35}, {"n": "Religião", "b": 35}], "resist": "Imune: Condições, dano", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 10d8 mental"}, {"n": "Destronar o Anfitrião", "acao": "Passiva", "desc": "A Máscara do Desespero é a única que consegue resolver o Enigma de Medo do Anfitrião."}, {"n": "Potência do Conhecimento", "acao": "Passiva", "desc": "O modificador da Máscara do Desespero para todos os testes de perícia baseados em Intelecto, Presença e Vigor é +35, e para testes baseados nos demais atributos, é +25."}, {"n": "Conjuração Verdadeira", "acao": "Livre", "desc": "Uma vez por turno, a Máscara do Desespero pode conjurar um ritual de Conhecimento a sua escolha, de qualquer círculo. O ritual deve ter execução máxima de ação completa e custo máximo de 20 PE. A DT para resistir a ele é 45."}, {"n": "Onipresença", "acao": "Movimento", "desc": "A Máscara do Desespero consegue se deslocar para qualquer local da Realidade, desde que haja algum tipo de sombra ou escuridão, independente da distância. Além disso, ela sabe exatamente tudo que está acontecendo na Realidade ao mesmo tempo. Isso faz com que nenhum personagem possa se esconder da relíquia, e ela ignora qualquer necessidade de ver ou ouvir para usar suas habilidades."}, {"n": "Reescrever Realidade", "acao": "Padrão", "desc": "A Máscara do Desespero tem o poder único de reescrever a Realidade por completo, alterando as propriedades de seres e objetos em alcance médio. Contra objetos, ela pode mudar a composição, posição e estado da matéria de um objeto de até 1 tonelada. Objetos vestidos ou empunhados têm direito a um teste de Reflexos do portador (DT 45) para evitar este efeito. Contra seres, ela pode causar 10d6 pontos de dano de Conhecimento, 10d6 pontos de dano mental e uma condição qualquer (exceto morrendo e enlouquecendo) em um ser (Vontade DT 45 reduz cada dano à metade e evita a condição)."}], "desc": "", "def": 55}'::jsonb),
(8,'Ocioso','Conhecimento','260',244,'{"tamanho": "Grande", "pv": 390, "desloc": 0.0, "atr": {"agi": 1, "for": 5, "int": 1, "pre": 5, "vig": 3}, "fort": 15, "refl": 0, "vont": 20, "ini": 0, "perc": 15, "pericias": [], "resist": "Balístico, corte, impacto e Conhecimento 20", "vuln": "Sangue", "sentidos": "Percepção", "ataques": [], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 8d6 mental NEX 80%+ é imune"}, {"n": "Sempre Presente", "acao": "Passiva", "desc": "No começo de uma cena, o ocioso escolhe um personagem que possa ver para ser seu alvo. O alvo é o único ser que consegue enxergar o ocioso; para todos os demais, ele é invisível."}, {"n": "Retaliação", "acao": "Reação", "desc": "Toda vez que for atacado ou alvo de uma habilidade, o ocioso se teletransporta para ficar adjacente ao atacante e faz um ataque corpo a corpo contra ele (teste 5 O +30, dano 4d10+20 de impacto não letal)."}, {"n": "Permanecer Próximo", "acao": "Livre", "desc": "Uma vez por rodada, o ocioso pode se teletransportar para qualquer ponto dentro do campo de visão do alvo."}, {"n": "Aterrorizar", "acao": "Completa", "desc": "O ocioso fica lá. Parado. Seu corpo distorcido e olhar profundo parecem entrar na alma do alvo, que sofre 4d10+10 pontos de dano mental se estiver adjacente. 244 Ocioso"}], "desc": "", "def": 37}'::jsonb),
(9,'Parasita de Culpa','Conhecimento','60',246,'{"tamanho": "Médio", "pv": 90, "desloc": 6.0, "atr": {"agi": 2, "for": 0, "int": 4, "pre": 4, "vig": 1}, "fort": 10, "refl": 10, "vont": 10, "ini": 0, "perc": 0, "pericias": [], "resist": "Imune: Dano (exceto causado pelo hospedeiro)", "vuln": "", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo", "teste": 0, "dano": "1d4 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 2d6 mental NEX 35%+ é imune"}, {"n": "Devorar Culpa", "acao": "Passiva", "desc": "O parasita se alimenta da culpa e dos traumas de um hospedeiro. Caso se fixe em um personagem dormindo, o parasita expande sua influência. Todos os personagens dormindo em alcance médio ficarão presos em um sonho compartilhado (veja Enigma de Medo) até que o parasita seja derrotado ou o hospedeiro morra ou enlouqueça."}, {"n": "Fixar", "acao": "Completa", "desc": "O parasita se aproxima de um personagem dormindo. O personagem tem direito a um teste de Percepção (com penalidade de – OO , por estar dormindo), oposto ao teste de Furtividade do parasita (2 O +15). Se passar, desperta antes que o parasita se fixe nele, fazendo com que a criatura fuja. Se falhar, torna-se hospedeiro do parasita (veja Devorar Culpa)."}, {"n": "Atormentar", "acao": "Completa", "desc": "Se estiver fixado a um hospedeiro, o parasita atormenta a mente do personagem e de todos que ele estiver mantendo inconscientes. No início de cada cena do sonho, todos os personagens dentro do sonho sofrem 2d6 pontos de dano mental (Vontade DT 20 reduz à metade)."}, {"n": "Cópias do Hospedeiro", "acao": "Completa", "desc": "Se estiver fixado a um hospedeiro, o parasita manifesta uma cópia feita de Conhecimento desse personagem. A cópia possui as mesmas estatísticas do original, mas tem 20 PV e todo dano que causa é de Conhecimento. O parasita pode manifestar no máximo quatro cópias por vez. Se manifestar uma cópia dentro do sonho, ela usa o valor de Presença do parasita no lugar dos seus atributos e causa dano mental em vez do normal."}], "desc": "", "def": 15}'::jsonb),
(10,'Rastejador Sombrio','Conhecimento','180',248,'{"tamanho": "Médio", "pv": 330, "desloc": 12.0, "atr": {"agi": 4, "for": 3, "int": 3, "pre": 3, "vig": 3}, "fort": 15, "refl": 15, "vont": 10, "ini": 15, "perc": 15, "pericias": [{"n": "Furtividade", "b": 15}, {"n": "Ocultismo", "b": 15}], "resist": "Balístico, corte e impacto 10, Conhecimento 20", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Toque da Dor", "alc": "Corpo a corpo x3", "teste": 20, "dano": "4d8+5 Conhecimento"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 25 6d6 mental NEX 60%+ é imune"}, {"n": "Vulnerabilidade a Luz", "acao": "Passiva", "desc": "Enquanto estiver exposto diretamente a uma fonte de luz forte, capaz de iluminar a criatura por completo, o rastejador sofre –10 em Defesa e perde as habilidades Desespero, Rastejar e Tentáculos das Sombras."}, {"n": "Desespero", "acao": "Livre", "desc": "O toque do rastejador desperta uma sensação de dor e agonia em suas vítimas. Sempre que um ser sofre dano do toque da dor, sofre a mesma quantidade de dano mental (Vontade DT 25 reduz o dano mental à metade). Rastejador Sombrio 224488"}, {"n": "Rastejar", "acao": "Livre", "desc": "O rastejador usa as sombras para se aproximar de seus alvos. Até o início do seu próximo turno, se estiver sob cobertura ou camuflagem parcial, o rastejador recebe +10 em Furtividade e não terá o deslocamento reduzido por se mover furtivamente."}, {"n": "Tentáculos das Sombras", "acao": "Movimento", "desc": "O rastejador coloca suas garras no chão e as fibras que compõem seu corpo são projetadas pelas sombras a até três seres em alcance médio, que ficam agarrados por elas (Reflexos DT 28 evita). Com uma ação de movimento, o rastejador pode arrastar até três vítimas agarradas dessa maneira para outros pontos em alcance médio de si. Em seu turno, um ser pode tentar se soltar como normal. No final de cada um dos seus turnos, um ser que esteja agarrado desta forma sofre 4d6 pontos de dano mental."}], "desc": "", "def": 41}'::jsonb),
(11,'Silhueta','Conhecimento','360',250,'{"tamanho": "Médio", "pv": 500, "desloc": 12.0, "atr": {"agi": 4, "for": 4, "int": 5, "pre": 5, "vig": 4}, "fort": 20, "refl": 20, "vont": 25, "ini": 20, "perc": 25, "pericias": [], "resist": "Dano 30", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 8d8 mental"}, {"n": "Aura Tangível", "acao": "Passiva", "desc": "Qualquer ser ou item que tocar na silhueta sofre 20d12 pontos de dano de Conhecimento (Fortitude DT 42 reduz à metade) e, se reduzido a 0 PV, é instantaneamente desintegrado. Um ser ou item só sofre esse dano uma vez por turno."}, {"n": "Conhecimento Verdadeiro", "acao": "Passiva", "desc": "A silhueta alcançou o Outro Lado através do Conhecimento e, por isso, sabe tudo. Ela faz testes baseados em Intelecto e Presença com +25 e testes baseados em Agilidade, Força e Vigor com +20."}, {"n": "Reescrever a Realidade", "acao": "Livre", "desc": "Enquanto estiver se deslocando, a silhueta pode reescrever e mudar a Realidade com seus sigilos de Conhecimento. Todos os objetos em alcance curto podem ser transformados em outros, desde que conservem o mesmo tamanho. Seres vivos e o equipamento que estiverem vestindo ou portando não são afetados por essa habilidade."}, {"n": "Toque Devastador", "acao": "Padrão", "desc": "A silhueta raramente age de maneira agressiva, mas quando precisa remover algo de seu caminho ela simplesmente o toca, causando o dano de sua aura tangível. A silhueta pode tocar até dois seres e/ou objetos com esta ação."}], "desc": "", "def": 55}'::jsonb),
(12,'Vulto','Conhecimento','40',251,'{"tamanho": "Médio", "pv": 60, "desloc": 12.0, "atr": {"agi": 4, "for": 2, "int": 2, "pre": 2, "vig": 1}, "fort": 0, "refl": 5, "vont": 5, "ini": 5, "perc": 5, "pericias": [{"n": "Furtividade", "b": 10}], "resist": "Balístico, corte e perfuração 5, Conhecimento 10", "vuln": "Sangue", "sentidos": "Percepção às cegas", "ataques": [{"n": "Toque Macabro", "alc": "Corpo a corpo x2", "teste": 10, "dano": "2d6 Conhecimento"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 3d6 mental NEX 30%+ é imune"}, {"n": "Aura Tangível", "acao": "Passiva", "desc": "O vulto procura pessoas assustadas para que possa se alimentar dos sentimentos disparados pelos sustos. Seus ataques contra criaturas sob efeito de qualquer condição de medo causam +2d6 pontos de dano de Conhecimento."}, {"n": "Plantar Paranoia", "acao": "Completa", "desc": "O vulto procura implantar medo e paranoia na mente de suas vítimas ao chacoalhar a Membrana e fazer aparecer coisas que não estão lá de verdade. Cada personagem em alcance médio fica abalado (Vontade DT 15 evita). Se o personagem já estiver abalado, ficará apavorado. Se o vulto estiver escondido ao usar essa habilidade, cada personagem sofre – O no teste de Vontade."}], "desc": "", "def": 19}'::jsonb),
(13,'Anfitrião','Energia','413',278,'{"tamanho": "Médio", "pv": 1413, "desloc": 12.0, "atr": {"agi": 7, "for": 5, "int": 6, "pre": 6, "vig": 5}, "fort": 25, "refl": 35, "vont": 25, "ini": 35, "perc": 25, "pericias": [], "resist": "Imune: Condições de paralisia, dano, dano e efeitos de Energia", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Corte Caótico", "alc": "Corpo a corpo", "teste": 45, "dano": "3d12+20 Energia"}, {"n": "Lança e Adaga", "alc": "Corpo a corpo x2", "teste": 45, "dano": "2d12+20 Energia"}, {"n": "Corte de Água", "alc": "Corpo a corpo", "teste": 45, "dano": "5d12+20 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 10d8 mental"}, {"n": "Transformar a Morte", "acao": "Passiva", "desc": "O caos ilógico do Anfitrião é a única coisa capaz de enfrentar a onipresença temporal do Deus da Morte e resolver o seu Enigma de Medo."}, {"n": "Potência de Energia", "acao": "Passiva", "desc": "O modificador do Anfitrião para todos os testes de perícia baseados em Agilidade e Intelecto é +35, e para testes baseados nos demais atributos, é +25."}, {"n": "Ato 1", "acao": "Passiva", "desc": "O Anfitrião inicia um combate se dividindo em 5 facetas separadas: Amphitruo, Aeneas, Liber, Silenus e Plautus . Cada um desses possui as mesmas estatísticas que o Anfitrião, mas possuem 250 PV cada e resistência a dano 20. Além disso, cada um só pode usar habilidades e ataques que tenham seu nome. Quando todos forem destruídos, o Anfitrião retorna para sua forma única e inicia o Ato 2 (veja abaixo)."}, {"n": "Ato 2", "acao": "Passiva", "desc": "No segundo Ato, o Anfitrião retorna para sua forma única, com todos seus PV. Ele pode usar todas as habilidades de sua ficha, incluindo aquelas de suas cinco facetas, e pode executar 3 ações padrão por rodada, desde que sejam diferentes."}, {"n": "Trilha Sonora (ato 2)", "acao": "Passiva", "desc": "Durante o Ato 2, a trilha sonora do Anfitrião toca em todo o ambiente. No início de cada turno do Anfitrião, cada ser em alcance longo sofre 2d10 pontos de dano mental."}, {"n": "Roleta Maluca (ato 2)", "acao": "Passiva", "desc": "No começo do turno do Anfitrião, cada ser em alcance longo sofre um efeito determinado aleatoriamente. Jogue 1d6 para cada ser na área; efeitos iguais são cumulativos: 1 Sofre –5 na Defesa até o final da cena. 2 Deve usar uma ação completa fazendo coisas sem sentido ou sofre 4d10 pontos de dano mental no final do seu turno. 3 Sofre 4d20 pontos de dano de Energia. 4 Sofre – O em Pontaria até o final da cena. 5 Sofre – O em Luta até o final da cena. 6 Nada acontece."}, {"n": "Teatro ( Amphitruo )", "acao": "Padrão", "desc": "O Anfitrião envia a imagem de um texto praticamente incompreensível para a mente do alvo, que deve decorá-lo em poucos segundos e recitá-lo com perfeição ou sofre 10d6 pontos de dano mental (Artes DT 35 ou Vontade DT 45 evita)."}, {"n": "Queimar ( Aeneas )", "acao": "Padrão", "desc": "O Anfitrião dispara chamas em um cone em alcance médio. Todos os seres nessa área sofrem 10d6+20 pontos de dano de Energia (Reflexos DT 45 reduz à metade)."}, {"n": "Agredir ( Liber )", "acao": "Padrão", "desc": ""}, {"n": "Romance Forçado ( Liber )", "acao": "Livre", "desc": "Se acertar um ser com seu golpe caótico, o Anfitrião pode escolher outro ser que consiga ver. Os dois seres devem decidir entre si quem sofrerá o dano do ataque (isso deve ser feito antes do dano ser definido)."}, {"n": "Agredir ( Plautus )", "acao": "Padrão", "desc": ""}, {"n": "Eu Sou o Caos ( Plautus )", "acao": "Livre", "desc": "Se acertar um ataque de lança e adaga em um ser desprevenido ou flanqueado, o Anfitrião causa +4d12 pontos de dano de Energia."}, {"n": "Agredir ( Silenus )", "acao": "Padrão", "desc": ""}, {"n": "Afogamento ( Silenus )", "acao": "Livre", "desc": "Um ser que sofra dano de corte de água fica asfixiado (Fortitude DT 35 evita). Um ser que esteja afixiado dessa forma pode repetir o teste de Fortitude no fim de cada um de seus turnos; se passar, a condição termina."}, {"n": "Teletransporte", "acao": "Movimento", "desc": "O Anfitrião se transporta para outro ponto em alcance médio. Amphitruo Aeneas Liber Silenus Plautus Anfitrião"}], "desc": "", "def": 59}'::jsonb),
(14,'Anomalia','Energia','380',261,'{"tamanho": "Médio", "pv": 1000, "desloc": 0.0, "atr": {"agi": 0, "for": 0, "int": 5, "pre": 5, "vig": 0}, "fort": 0, "refl": 15, "vont": 15, "ini": 0, "perc": 0, "pericias": [], "resist": "Imune: Dano e todas as condições", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 9d8 mental"}, {"n": "Imaterial", "acao": "Passiva", "desc": "A anomalia possui um corpo físico desprezível e escondido atrás de uma imensidão de Energia paranormal. Ela é imune a dano e a todas as condições. A anomalia não faz testes e não age da mesma maneira que outras criaturas. Sua própria existência é uma impossibilidade e um confronto com ela é surreal e indescritível. A única forma de derrotá-la é resolvendo seu Enigma de Medo."}, {"n": "Existência Impossível", "acao": "Passiva", "desc": "A anomalia não se desloca de maneira normal. Ela existe somente dentro de um objeto que possa ser aberto por uma porta. Enquanto a porta estiver aberta, a anomalia é manifestada e pode usar seus poderes. Uma vez manifestada, a anomalia ficará perseguindo aqueles que a manifestaram, surgindo sempre que abrirem uma porta ou compartimento e levando-os à loucura."}, {"n": "Romper Consciência", "acao": "Livre", "desc": "No início do turno da anomalia, ela sorteia um ser que esteja em sua linha de visão e tenta romper sua razão transformando suas ondas cerebrais. A vítima sofre 10d6 pontos de dano mental (Vontade DT 41 reduz à metade) e, se ficar insana devido a este dano, é absorvida pela anomalia."}, {"n": "Manipular Ondas da Existência", "acao": "Livre", "desc": "No final do turno da anomalia, ela manipula as ondas eletromagnéticas que compõem a própria existência. Ela pode ativar, desativar ou operar até seis objetos tecnológicos em alcance médio. Como alternativa, pode sobrecarregar estes objetos, gerando uma poderosa descarga que causa 2d12 pontos de dano de Energia por objeto em todos os seres na área (Reflexos DT 30 reduz à metade)."}, {"n": "Manifestar o Impossível", "acao": "Completa", "desc": "A anomalia invoca uma ou mais criaturas de Energia cujo VD total some até 240. As criaturas aparecem em alcance curto da anomalia e agem a partir da próxima rodada, seguindo seus impulsos caóticos."}], "desc": "", "def": 0}'::jsonb),
(15,'Anomiático','Energia','240',263,'{"tamanho": "Médio", "pv": 600, "desloc": 18.0, "atr": {"agi": 5, "for": 3, "int": 1, "pre": 4, "vig": 3}, "fort": 10, "refl": 20, "vont": 15, "ini": 15, "perc": 10, "pericias": [], "resist": "Balístico, corte e perfuração 10, Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Garra Desintegradora", "alc": "Corpo a corpo x2", "teste": 30, "dano": "4d12+20 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 30 6d8 mental NEX 75%+ é imune"}, {"n": "Comportamento Errático", "acao": "Livre", "desc": "No começo do seu turno, o anomiático é tomado pelo fluxo de Energia em seu corpo e executa três comportamentos aleatórios. Role 1d6 na tabela abaixo três vezes; o anomiático então executa as ações indicadas na ordem em que forem roladas. Se não puder executar uma das ações, ele fica parado se contorcendo e perde aquela ação (mas não qualquer outra). Para cada ação que perder, o anomiático aumenta suas resistências a dano em 10 até seu próximo turno. 1 2 O anomiático salta até 18m em direção ao ser mais próximo. Se ficar adjacente a ele, faz uma ação agredir e ataca com suas garras desintegradoras. 3 O anomiático se transforma em um facho de Energia e se move até ficar adjacente a um ser escolhido aleatoriamente entre todos que o estejam enfrentando. 4 Uma parte do corpo do anomiático explode, causando dano de Energia em todos os seres ao redor. O dano exato depende da distância do ser em relação ao anomiático: 4d12+20 para seres em alcance médio, 6d12+20 para seres em alcance curto e 8d12+20 para seres adjacentes. Seres em alcance médio ou curto têm direito a um teste de Reflexos (DT 30) para reduzir o dano à metade. O anomiático perde 50 PV quando executa esta ação. 5 Uma risada descontrolada toma o anomiático. Ele fica desprevenido até o início do seu próximo turno. Enquanto estiver desprevenido, todos os seus ataques são mais imprevisíveis e o defensor não pode se esquivar deles. 6 O anomiático toca um ser adjacente. O alvo acumula uma quantidade absurda de Energia e sofre 10d12+20 pontos de dano de Energia (Fortitude DT 30 reduz à metade)."}], "desc": "", "def": 41}'::jsonb),
(16,'Anárquico','Energia','20',257,'{"tamanho": "Médio", "pv": 30, "desloc": 9.0, "atr": {"agi": 3, "for": 2, "int": 0, "pre": 0, "vig": 1}, "fort": 0, "refl": 10, "vont": 0, "ini": 5, "perc": 0, "pericias": [], "resist": "Energia 5", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Pancada Errática", "alc": "Corpo a corpo", "teste": 5, "dano": "2d12 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 14 2d6 mental NEX 25%+ é imune"}, {"n": "Comportamento Errático", "acao": "Passiva", "desc": "No começo do seu turno, o anárquico é tomado pelo fluxo de Energia em seu corpo e age de modo aleatório. Role 1d6 para determinar o que ele faz. Se não puder realizar a ação, fica parado se contorcendo, mas recebe resistência a dano 5 até o início do seu próximo turno. 1 2 O anárquico pula sobre o personagem mais próximo, fazendo a ação investida (ou a ação agredir, se estiver muito próximo do personagem). Se não conseguir atacar alguém, corre na direção do personagem mais próximo. 3 4 O anárquico projeta uma luz prismática de dentro de si na direção de um ser em alcance médio. O alvo sofre 2d8 pontos de dano de Energia e fica atordoado por uma rodada (Fortitude DT 14 reduz o dano à metade e evita a condição). 5 Uma explosão de Energia emana do anárquico. Cada ser em alcance curto sofre 2d6 pontos de dano de Energia (Reflexos DT 14 reduz à metade). Seres adjacentes ao anárquico sofrem +1d6 pontos de dano. 6 Uma risada descontrolada toma o anárquico enquanto ele faz a ação agredir contra o personagem mais próximo. Até o final de seu próximo turno, o anárquico fica desprevenido, mas seus ataques ficam completamente imprevisíveis e o defensor não pode se esquivar deles."}], "desc": "", "def": 21}'::jsonb),
(17,'Anárquico Descontrolado','Energia','120',259,'{"tamanho": "Médio", "pv": 120, "desloc": 12.0, "atr": {"agi": 4, "for": 3, "int": 2, "pre": 2, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 10, "perc": 5, "pericias": [], "resist": "Balístico, corte e perfuração 10, Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Pancada Energética", "alc": "Corpo a corpo x2", "teste": 15, "dano": "4d12 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 21 4d6 mental NEX 50%+ é imune"}, {"n": "Aceleração", "acao": "Livre", "desc": "Sempre que um personagem sofre dano da pancada energética, entra em estado de aceleração e pode sofrer dano colateral. Em seu próximo turno, se realizar uma ação de movimento e uma ação padrão, ou uma ação completa), o personagem acelerado sofre 4d12 pontos de dano de Energia."}, {"n": "Autodestruição", "acao": "Movimento", "desc": "O anárquico concentra Energia no seu corpo e se autodestrói, causando 8d12 pontos de dano de Energia em todos os personagens em alcance curto (Reflexos DT 25 reduz à metade). Personagens adjacentes ao anárquico descontrolado sofrem – OO neste teste de resistência. O anárquico descontrolado morre após usar essa habilidade."}], "desc": "", "def": 28}'::jsonb),
(18,'Ciborgue','Energia','80',265,'{"tamanho": "Grande", "pv": 160, "desloc": 9.0, "atr": {"agi": 3, "for": 3, "int": 2, "pre": 2, "vig": 3}, "fort": 10, "refl": 5, "vont": 0, "ini": 10, "perc": 5, "pericias": [], "resist": "Balístico, corte e perfuração 10, Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Braço Laminado", "alc": "Corpo a corpo x2, crítico 18", "teste": 10, "dano": "1d12+10 corte"}, {"n": "Punho Energizado", "alc": "Corpo a corpo", "teste": 10, "dano": "2d8+10 impacto"}, {"n": "Canhão", "alc": "Distância LONGO", "teste": 10, "dano": "4d12+5 Energia"}, {"n": "Raio Energético", "alc": "Distância", "teste": 10, "dano": "1d12+5 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 2d6 mental NEX 40%+ é imune"}, {"n": "Estado de Combate", "acao": "Passiva", "desc": "No começo do turno do ciborgue, ele assume um estado de combate disponível dentre os quatro abaixo. Um estado de combate deixa de estar disponível quando sua fraqueza é resolvida (veja Enigma de Medo). O estado de combate do ciborgue define quais ações ele pode fazer, conforme a coluna ao lado. Estado Alpha. Focado em atacar inimigos próximos. Estado Beta. Focado em perseguir e atacar inimigos distantes. Estado Gama. Focado em ataques à distância. Estado Delta. Estado tático e defensivo."}, {"n": "Regeneração Energética", "acao": "Passiva", "desc": "No começo do turno do ciborgue, ele recupera 20 PV. Se perder três ou mais estados de combate, o ciborgue perde esta habilidade."}, {"n": "Investida Energética", "acao": "Completa", "desc": "O ciborgue avança até 24m (18 ) e faz um ataque de punho energizado com bônus de + O no teste de ataque. Se acertar, causa +2d8 de dano (para um total de 4d8+10) e derruba o alvo (Fortitude DT 20 evita a queda). Estado GAMA"}, {"n": "Agredir (gama)", "acao": "Padrão", "desc": "Estado DELTA"}, {"n": "Criar Barreira", "acao": "Movimento", "desc": "O ciborgue expande suas correntes de Energia e cria uma barreira paranormal. Ele recebe +5 na Defesa até o início de seu próximo turno."}, {"n": "Reiniciar", "acao": "Movimento", "desc": "O ciborgue encerra uma condição que o esteja afetando."}, {"n": "Desorientar", "acao": "Livre", "desc": "Um ser que sofra dano do raio energético fica alquebrado. Se já estiver alquebrado, fica atordoado por uma rodada (Vontade DT 20 evita)."}], "desc": "", "def": 25}'::jsonb),
(19,'Infecticídio','Energia','280',267,'{"tamanho": "Enorme", "pv": 600, "desloc": 9.0, "atr": {"agi": 3, "for": 5, "int": 1, "pre": 1, "vig": 5}, "fort": 20, "refl": 15, "vont": 15, "ini": 15, "perc": 10, "pericias": [], "resist": "Balístico, corte, perfuração e Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Pancadas Infectadas", "alc": "Corpo a corpo x3", "teste": 30, "dano": "4d12+20 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 8d6 mental NEX 85%+ é imune"}, {"n": "Horda", "acao": "Passiva", "desc": "O infecticídio é uma horda de criaturas infectadas por um vírus de Energia. Ele sofre apenas metade do dano de ataques e habilidades que afetem apenas um ser, mas sofre o dobro do dano de efeitos de área. Além disso, sempre que erra um ataque, ainda causa metade do dano (exceto se o defensor usou uma reação para se esquivar)."}, {"n": "Infecção", "acao": "Livre", "desc": "Um ser que sofra dano das pancadas é infectado pelo vírus do infecticídio (Fortitude DT 30 evita; veja página 292). Um ser que passe no teste de resistência fica imune a essa doença até final da cena."}, {"n": "Consumação Insidiosa", "acao": "Reação", "desc": "Se reduzir um ser a 0 PV com suas pancadas infectadas, o infecticídio consome a vítima, recuperando 50 PV."}, {"n": "Atropelar", "acao": "Completa", "desc": "O infecticídio percorre até o dobro do seu deslocamento, podendo passar pelo espaço de outros seres. Durante esse deslocamento, ele faz um ataque de pancada infectada contra cada ser nos espaços pelos quais passar."}], "desc": "", "def": 25}'::jsonb),
(20,'Perturbado de Energia','Energia','40',268,'{"tamanho": "Médio", "pv": 60, "desloc": 9.0, "atr": {"agi": 4, "for": 1, "int": 0, "pre": 0, "vig": 0}, "fort": 0, "refl": 10, "vont": 0, "ini": 10, "perc": 0, "pericias": [], "resist": "Balístico, corte e perfuração 5, Energia 10", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Toque Plasmático", "alc": "", "teste": 10, "dano": "2d12 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 2d8 mental NEX 30%+ é imune"}, {"n": "Toque Plasmático", "acao": "Padrão", "desc": "Corpo a corpo x2"}, {"n": "Implantar Confusão", "acao": "Livre", "desc": "Uma vez por rodada, o perturbado de Energia tenta agarrar um personagem que acabou de sofrer dano de seu toque plasmático (teste 4d O +10). Se conseguir, o perturbado começa a implantar imagens na mente do alvo e fazer com que ele reviva experiências traumáticas. O personagem sofre 2d8 pontos de dano mental (Vontade DT 15 reduz à metade) e recebe vulnerabilidade a dano de Energia até o fim da cena."}], "desc": "", "def": 19}'::jsonb),
(21,'Sukkalgir','Energia','160',269,'{"tamanho": "Médio", "pv": 220, "desloc": 18.0, "atr": {"agi": 3, "for": 2, "int": 3, "pre": 3, "vig": 2}, "fort": 5, "refl": 10, "vont": 15, "ini": 10, "perc": 10, "pericias": [], "resist": "Impacto e Energia 10", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Mordida do Outro Lado", "alc": "", "teste": 15, "dano": "2d12 mental"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 25 4d8 mental NEX 55%+ é imune"}, {"n": "Aura Desesperada", "acao": "Passiva", "desc": "Qualquer ser que comece seu turno em alcance curto da sukkalgir sofre 2d12 pontos de dano mental (Vontade DT 25 reduz à metade)."}, {"n": "Espírito Plasmático", "acao": "Passiva", "desc": "A sukkalgir é parcialmente intangível, e pode atravessar obstáculos sólidos como paredes."}, {"n": "Mordida do Outro Lado", "acao": "Padrão", "desc": "Corpo a corpo x2"}, {"n": "Agarrão", "acao": "Livre", "desc": "Se a sukkalgir acertar um ataque com sua mordida em um ser Médio ou menor, pode agarrar o alvo (teste 3 O +15)."}, {"n": "Grito de Desespero", "acao": "Completa", "desc": "A sukkalgir grita em desespero. Cada ser em alcance médio sofre 3d12 pontos de dano mental (Vontade DT 20 reduz à metade; estar sob cobertura fornece +5 nesse teste). Sukkalgir"}], "desc": "", "def": 34}'::jsonb),
(22,'Telopsia','Energia','340',271,'{"tamanho": "Médio", "pv": 560, "desloc": 12.0, "atr": {"agi": 4, "for": 2, "int": 3, "pre": 5, "vig": 2}, "fort": 15, "refl": 20, "vont": 25, "ini": 20, "perc": 25, "pericias": [{"n": "Furtividade", "b": 20}], "resist": "Balístico, corte, perfuração e Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Toque Desintegrador", "alc": "Corpo a corpo x3", "teste": 35, "dano": "6d12+30 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 10d6 mental NEX 99%+ é imune"}, {"n": "Viajar Pela Tela", "acao": "Movimento", "desc": "O telopsia pode se desmaterializar e se materializar em outra tela ou visor em alcance longo. Em seguida, ele se desloca 9m."}, {"n": "Tela Zumbificadora", "acao": "Padrão", "desc": "O telopsia projeta imagens enlouquecedoras em sua tela. Todos os seres em alcance médio sofrem 6d6 pontos de dano mental e ficam confusos até o final da cena (Vontade DT 30 reduz o dano à metade e evita a condição). Um ser que já esteja confuso e falhe no teste de resistência fica também fascinado."}, {"n": "Prender Na Tela", "acao": "Completa", "desc": "O telopsia usa ondas de Energia para desintegrar um ser em alcance curto e materializá-lo dentro de sua tela (Fortitude DT 30 evita). Um ser dentro da tela fica paralisado e sofre 2d12 pontos de dano mental no início de cada um de seus turnos. Cada vez que o telopsia sofre 50 ou mais pontos de dano em um turno, o ser preso pode repetir o teste de Fortitude; se passar, escapa da tela e se materializa em um ponto a sua escolha adjacente ao telopsia."}], "desc": "", "def": 48}'::jsonb),
(23,'Tempestuoso','Energia','360',273,'{"tamanho": "Médio", "pv": 950, "desloc": 24.0, "atr": {"agi": 5, "for": 4, "int": 2, "pre": 5, "vig": 4}, "fort": 20, "refl": 30, "vont": 25, "ini": 25, "perc": 20, "pericias": [], "resist": "Balístico, corte, perfuração e Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Garras Radioativas", "alc": "Corpo a corpo x2*", "teste": 40, "dano": "4d20+20 Energia"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 8d8 mental"}, {"n": "Aura Radioativa", "acao": "Passiva", "desc": "Qualquer ser que comece seu turno em alcance curto do tempestuoso sofre 2d20+20 pontos de dano de Energia (Fortitude DT 40 reduz à metade)."}, {"n": "Espectro Radioativo", "acao": "Passiva", "desc": "O tempestuoso manifesta um espectro de radiação à sua volta, que atua como uma extensão de seu corpo físico. Todos os ataques e habilidades corpo a corpo do tempestuoso podem ser feitos em alcance curto."}, {"n": "Raio de Energia Radioativa", "acao": "Livre", "desc": "Quando acerta dois ataques de garras radioativas em um mesmo ser, o tempestuoso faz com que um raio de energia radioativa seja projetado deste ser em direção a outro alvo em alcance médio. Este alvo sofre 4d20+20 pontos de dano de Energia (Reflexos DT 40 reduz à metade)."}, {"n": "Expandir Em Radiação", "acao": "Completa", "desc": "O tempestuoso concentra energia radioativa em volta de si para depois expandi-la como uma explosão de Energia. Cada ser em alcance longo sofre 10d20+20 pontos de dano de Energia (Reflexos DT 40 reduz à metade). O próprio tempestuoso perde 100 PV quando usa esta habilidade."}], "desc": "", "def": 56}'::jsonb),
(24,'Viajante','Energia','200',274,'{"tamanho": "Médio", "pv": 360, "desloc": 9.0, "atr": {"agi": 4, "for": 2, "int": 3, "pre": 4, "vig": 2}, "fort": 10, "refl": 15, "vont": 15, "ini": 15, "perc": 15, "pericias": [], "resist": "Balístico, corte e perfuração 10, Energia 20", "vuln": "Conhecimento", "sentidos": "Visão no escuro", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo x2", "teste": 15, "dano": "2d12+10 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 6d6 mental NEX 60%+ é imune"}, {"n": "Invisibilidade Permanente", "acao": "Passiva", "desc": "O viajante é invisível. Ele recebe camuflagem total, +15 em Furtividade e seres que não possam vê-lo ficam desprevenidos contra seus ataques."}, {"n": "Agarrão", "acao": "Livre", "desc": "Se o viajante acerta um ataque com sua pancada em um ser Médio ou menor, pode tentar agarrar o alvo (teste 2 O +15)."}, {"n": "Devorar Memória", "acao": "Completa", "desc": "O viajante entra na mente de um ser que esteja agarrando e começa a devorar suas memórias. A vítima sofre 4d12 pontos de dano mental e esquece completamente de uma pessoa (Vontade DT 29 reduz o dano à metade e evita o efeito). Para cada ser que o viajante deixar perturbado com esta habilidade, seu dano de pancada aumenta em +1d12 até o fim da cena."}], "desc": "", "def": 34}'::jsonb),
(25,'Degolificada','Medo','320',282,'{"tamanho": "Médio", "pv": 850, "desloc": 6.0, "atr": {"agi": 3, "for": 5, "int": 3, "pre": 4, "vig": 4}, "fort": 20, "refl": 15, "vont": 25, "ini": 0, "perc": 15, "pericias": [], "resist": "Imune: Dano", "vuln": "", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo x2", "teste": 35, "dano": "8d8+20 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 9d6 mental NEX 95%+ é imune"}, {"n": "Criatura de Medo", "acao": "Passiva", "desc": "A degolificada é imune a dano, até que se resolva o mistério da sua origem."}], "desc": "", "def": 45}'::jsonb),
(26,'Aracnasita','Morte','80',209,'{"tamanho": "Grande", "pv": 140, "desloc": 12.0, "atr": {"agi": 3, "for": 2, "int": 1, "pre": 1, "vig": 2}, "fort": 5, "refl": 10, "vont": 5, "ini": 10, "perc": 10, "pericias": [{"n": "Furtividade", "b": 8}], "resist": "Imune: Dano", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 15, "dano": "2d10+10 perfuração"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 4d6 mental NEX 40%+ é imune"}, {"n": "Percepção Tátil", "acao": "Passiva", "desc": "A aracnasita percebe tudo que está em contato com sua teia. Ela ignora penalidades por visão ou condições de sentidos para objetos e seres em contato com a teia."}, {"n": "Estacar", "acao": "Livre", "desc": "Quando causa dano com sua mordida, a aracnasita pode usar seu Lodo da Morte para prender o alvo no lugar. A vítima sofre +1d10 pontos de dano de Morte e fica agarrada. Ela pode se soltar gastando uma ação padrão e um teste de Atletismo (DT 20). Personagens adjacentes podem gastar uma ação padrão para soltá-la com o mesmo teste (ou ajudá-la em seu próprio teste)."}, {"n": "Desovar Aranhas", "acao": "Reação", "desc": "Uma vez por cena, quando ficar machucada, a aracnasita desova diversas aranhas menores, que se espalham em sua volta gerando efeitos diversos. No início de cada turno da aracnasita após isso, ela executa um dos seguintes efeitos, nesta ordem. No primeiro turno, as aranhas se espalham ao redor da aracnasita. Até o fim da cena, um personagem que inicie seu turno em alcance curto da criatura sofre 2d6 pontos de dano mental (Vontade DT 15 reduz à metade). A partir do segundo turno, as aranhas atacam os personagens ao redor da aracnasita. Até o fim da cena, um personagem que inicie seu turno em alcance curto da criatura sofre 2d8 pontos de dano de Morte (Fortitude DT 15 reduz à metade). No terceiro turno, as aranhas menores se espalham ainda mais. Os dois efeitos acima agora afetam personagens que iniciem seu turno em alcance médio da aracnasita. A partir do quarto turno, caso um personagem morra em alance médio da aracnasita, será consumido por uma aranha, que irá se transformar em uma nova aracnasita com 70 PV e sem a habilidade Desovar Aranhas."}, {"n": "Disparar Teia", "acao": "Movimento", "desc": "A aracnasita dispara uma teia em alcance curto. A teia ocupa uma área quadrada com 3m de lado. Personagens na área ou que entrem nela, ficam agarrados (Reflexos DT 20 evita). A teia é tomada pelo Lodo da Morte, fazendo com que qualquer personagem que inicie seu turno agarrado por ela sofra 2d8+10 pontos de dano de Morte. Um personagem pode escapar da teia causando 15 pontos de dano de corte a ela ou gastando uma ação padrão para rasgá-la (Atletismo DT 20). A teia dura até fim da cena."}], "desc": "", "def": 23}'::jsonb),
(27,'Carniçal Preto da Morte','Morte','200',211,'{"tamanho": "Médio", "pv": 400, "desloc": 12.0, "atr": {"agi": 4, "for": 4, "int": 3, "pre": 3, "vig": 3}, "fort": 15, "refl": 15, "vont": 15, "ini": 15, "perc": 15, "pericias": [{"n": "Atletismo", "b": 15}], "resist": "Corte, impacto e perfuração 10, Morte 20", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garra da Morte", "alc": "Corpo a corpo x2", "teste": 25, "dano": "4d10+20 Morte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 30 6d6 mental NEX 65%+ é imune"}, {"n": "Físico Paranormal", "acao": "Passiva", "desc": "O carniçal possui um porte físico poderoso e pode saltar o dobro do deslocamento normal."}, {"n": "Instinto Mortal", "acao": "Passiva", "desc": "O carniçal age de maneira precisa e quase calculista, mas isso muda quando está machucado (com 200 PV ou menos). Nessa condição, ele usa a Hipnose como ação livre no começo de cada um de seus turnos e pode fazer um ataque adicional de garra da morte se atacar o mesmo alvo com suas duas garras."}, {"n": "Corpo Fechado", "acao": "Passiva", "desc": "Um ser que use a ação mirar para disparar na cabeça do carniçal ignora sua imunidade a dano balístico."}, {"n": "Pancada Poderosa", "acao": "Reação", "desc": "Quando desfere um acerto crítico com sua garra da Morte, o carniçal pode empurrar seu alvo 6m em qualquer direção. Se colidir com um objeto resistente, como uma parede ou um carro, a vítima sofre 4d6 pontos de dano de impacto. Se o objeto for outro ser, ambos sofrem esse dano."}, {"n": "Comando", "acao": "Movimento", "desc": "O carniçal dá um comando para um ser em alcance curto, que deve obedecer da forma mais eficiente possível (Vontade DT 29 evita). Em termos de regras, isso gera um dos efeitos básicos do ritual Perturbação (página 137)."}, {"n": "Hipnose", "acao": "Padrão", "desc": "O carniçal domina a mente de um ser em alcance curto (Vontade DT 29 evita). A vítima fica sob controle telepático total do carniçal, e fará tudo que ele mandar, exceto tirar sua própria vida — em termos de jogo, fica sob controle do mestre. No final de cada turno do ser hipnotizado, ele pode repetir o teste de Vontade, com um bônus cumulativo de +1 por teste já realizado. Se passar, sai do comando do carniçal. O carniçal pode ter até três seres hipnotizados por vez. Caso o carniçal use essa habilidade em um alvo enlouquecendo, o ser falha automaticamente e fica sob domínio permanente do carniçal (até que o carniçal seja destruído). Um ser nesta condição pode até mesmo tirar a própria vida, se assim for comandado."}, {"n": "Reanimar Corpos", "acao": "Completa", "desc": "Uma vez por cena, o carniçal usa a Morte para fazer com que até 2d4+2 corpos em alcance médio sejam reanimados. Os reanimados agem de maneira violenta e bestial, atacando o ser mais próximo até serem destruídos. Use a ficha do esqueleto de Lodo para esses corpos reanimados."}], "desc": "", "def": 38}'::jsonb),
(28,'Ceifador Espiral','Morte','380',213,'{"tamanho": "Grande", "pv": 999, "desloc": 15.0, "atr": {"agi": 5, "for": 5, "int": 5, "pre": 5, "vig": 5}, "fort": 25, "refl": 25, "vont": 25, "ini": 20, "perc": 20, "pericias": [], "resist": "Dano 50", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Foice da Morte", "alc": "Corpo a corpo x2", "teste": 40, "dano": "5d10+20 Morte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 9d8 mental"}, {"n": "Decepar", "acao": "Passiva", "desc": "Se o Ceifador Espiral faz um acerto crítico com sua foice da Morte, o alvo é reduzido a 25 PV e perde 1 ponto de Força, Agilidade ou Vigor permanentemente (decida aleatoriamente). Caso o alvo tenha 25 PV ou menos, morre de imediato. Toda vez que o Ceifador Espiral mata uma criatura, recebe 50 PV temporários, e seus ataques de foice da Morte causam +1d10 pontos de dano até o final da cena."}, {"n": "Transporte Pelo Pó", "acao": "Movimento", "desc": "Enquanto estiver dentro da área criada por sua habilidade Cinzas das Terras Desoladas, o Ceifador poderá usar uma ação de movimento para se transportar para outro espaço dentro dessa área. Quando terminar esse movimento, ele pode fazer um ataque com sua Foice da Morte como ação livre."}, {"n": "Contemplar a Espiral", "acao": "Completa", "desc": "O Ceifador Espiral usa sua foice para manifestar a verdadeira espiral da Morte. Todos os seres em alcance médio que consigam vê-lo sofrem 10d10+30 pontos de dano mental (Vontade DT 43 reduz à metade). Um ser que tenha sofrido dano desta habilidade fica imune a ela até final da cena."}, {"n": "Cinzas das Terras Desoladas", "acao": "Completa", "desc": "O Ceifador Espiral usa seus muitos braços para realizar um rito de invocação. Uma área de alcance longo em volta de si é tomada pelas cinzas das terras desoladas, um local acelerado pelo tempo onde tudo é transformado em pó. Cada ser dentro da área sofre 10d10+20 pontos de dano de Morte e fica enjoado (Fortitude DT 43 reduz o dano à metade e evita a condição). Um ser que termine seu turno dentro dessa área sofre 20 pontos de dano de Morte."}], "desc": "", "def": 58}'::jsonb),
(29,'Enraizado','Morte','120',214,'{"tamanho": "Médio", "pv": 140, "desloc": 9.0, "atr": {"agi": 3, "for": 3, "int": 1, "pre": 1, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 10, "perc": 10, "pericias": [{"n": "Atletismo", "b": 10}], "resist": "Corte, impacto e perfuração 10, Morte 20", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Punho Espinhento", "alc": "Corpo a corpo x2", "teste": 0, "dano": ""}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 4d6 mental NEX 50%+ é imune"}, {"n": "Imortalidade", "acao": "Passiva", "desc": "Quando o enraizado morre, se desfaz em uma poça de Lodo, galhos e raízes. Ele retornará após 1d2 rodadas com 70 PV. Se sofrer 20 pontos de dano de fogo ou de Energia somados enquanto estiver na forma de poça, será permanentemente destruído."}, {"n": "Veneno Pútrido", "acao": "Passiva", "desc": "A primeira vez que um personagem sofre dano do punho espinhento em uma cena, fica envenenado. No início de cada um de seus turnos, o personagem deve fazer um teste de Fortitude (DT 23). Se falhar, sofre 4d12 pontos de dano de Morte. Se passar, se cura do veneno."}], "desc": "", "def": 28}'::jsonb),
(30,'Escutado','Morte','160',216,'{"tamanho": "Médio", "pv": 290, "desloc": 12.0, "atr": {"agi": 4, "for": 3, "int": 1, "pre": 2, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 10, "perc": 10, "pericias": [], "resist": "Imune: Dano", "vuln": "", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo x2", "teste": 20, "dano": "3d6+10 perfuração"}, {"n": "Cabeça Arremessada", "alc": "", "teste": 15, "dano": "1d10+10 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 25 4d8 mental NEX 55%+ é imune"}, {"n": "Multiplicação Melódica", "acao": "Passiva", "desc": "No início do turno do escutado, se ele estiver ouvindo a melodia de sua criação, manifesta uma cópia sua em um ponto a sua escolha em alcance curto. A cópia possui 145 PV, não tem imunidade a dano e age junto com o escutado original, a partir do próximo turno dele. As cópias também possuem essa habilidade, gerando novas cópias caso aplicável. O escutado e suas cópias tentarão eliminar o ser que estiver tocando a melodia."}, {"n": "Cabeça Arremessada", "acao": "Padrão", "desc": "Distância x2 CURTO"}, {"n": "Vomitar Lodo", "acao": "Movimento", "desc": "Uma vez por cena, na primeira rodada após ser manifestada, cada cópia do escutado despeja um jorro de Lodo em um ser em alcance curto. O alvo sofre 4d10+10 pontos de dano de Morte e fica lento até o fim da cena (Reflexos DT 25 reduz o dano à metade e evita condição)."}], "desc": "", "def": 29}'::jsonb),
(31,'Esqueleto de Lodo','Morte','20',217,'{"tamanho": "Médio", "pv": 40, "desloc": 6.0, "atr": {"agi": 2, "for": 2, "int": 0, "pre": 1, "vig": 1}, "fort": 0, "refl": 5, "vont": 0, "ini": 0, "perc": 0, "pericias": [], "resist": "Corte, impacto e perfuração 5, Morte 10", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garras", "alc": "Corpo a corpo x2", "teste": 5, "dano": "2d6+2 corte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 14 2d4 mental NEX 25%+ é imune"}, {"n": "Imortalidade", "acao": "Passiva", "desc": "Quando o esqueleto morre, se desfaz em uma poça de Lodo e ossos. Ele retornará após 1d3 rodadas com 20 PV. Se sofrer dano de fogo ou de Energia enquanto estiver na forma de poça, será permanentemente destruído."}, {"n": "Espiral de Lodo", "acao": "Completa", "desc": "O esqueleto se transforma em uma poça de Lodo e se lança para frente como uma espiral perfurante que percorre até 9m em linha reta. Qualquer ser no caminho sofre 2d10 de dano de Morte (Reflexos DT 14 reduz à metade). O esqueleto então se reforma no fim do trajeto. Esqueleto de Lodo"}], "desc": "", "def": 14}'::jsonb),
(32,'Marionete','Morte','280',219,'{"tamanho": "Médio", "pv": 700, "desloc": 6.0, "atr": {"agi": 3, "for": 5, "int": 1, "pre": 5, "vig": 2}, "fort": 10, "refl": 15, "vont": 20, "ini": 15, "perc": 15, "pericias": [], "resist": "Corte, impacto, perfuração e Morte 20", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Foice Óssea", "alc": "Corpo a corpo x2", "teste": 30, "dano": "10d8+10 Morte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 8d6 mental NEX 85%+ é imune"}, {"n": "Momento Passivo", "acao": "Passiva", "desc": "Apesar de não ser rápida, a marionete não pode ter seu deslocamento reduzido e ignora qualquer tipo de terreno difícil. Além disso, ela não sofre dano ou efeitos que dependam que ela toque no chão."}, {"n": "Reflexos Guiados Por Corda", "acao": "Reação", "desc": "Uma vez por rodada, quando um ser se aproxima da marionete o suficiente para ficar adjacente, ela pode fazer um ataque de foice da morte contra esse ser."}, {"n": "Ironia do Destino", "acao": "Completa", "desc": "A marionete executa dois ataques com sua foice óssea em um ser adjacente. Se acertar o segundo ataque, ela agarra a vítima com a arma e pode se deslocar 6m carregando-a consigo. Enquanto estiver agarrando um ser, a marionete pode transferir parte de sua dor para ele — sempre que a criatura sofrer dano, se estiver agarrando um ser, o dano é dividido entre ela e o ser que ela estiver agarrando."}], "desc": "", "def": 40}'::jsonb),
(33,'Múmia Xipófaga','Morte','240',221,'{"tamanho": "Médio", "pv": 400, "desloc": 9.0, "atr": {"agi": 5, "for": 4, "int": 2, "pre": 3, "vig": 4}, "fort": 15, "refl": 15, "vont": 10, "ini": 15, "perc": 10, "pericias": [], "resist": "Corte, impacto e perfuração 10, Morte 20", "vuln": "Energia, fogo", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garra Enfaixada", "alc": "Corpo a corpo x2", "teste": 30, "dano": "4d8+30 corte"}, {"n": "Vomitar Lodo", "alc": "Distância x2 CURTO", "teste": 25, "dano": "3d6+30 Morte mais 3d8"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 30 6d8 mental NEX 75%+ é imune"}, {"n": "Faixas da Permanência", "acao": "Passiva", "desc": "Uma múmia reduzida a 0 PV não é destruída. Em vez disso, pode continuar agindo até o final do seu próximo turno. Se não terminar seu próximo turno com pelo menos 1 PV, ela morrerá."}, {"n": "Agarrada Mumificadora", "acao": "Livre", "desc": "Se a múmia acertar um ataque de garra enfaixada ela pode agarrar o alvo (teste 4 O +30). Enquanto estiver agarrada assim, a vítima sofre 4d8+30 pontos de dano de Morte no início de cada um dos seus turnos e a múmia recupera essa mesma quantidade de PV. Caso o ser seja reduzido a 0 PV dessa forma, se torna um esqueleto de Lodo no começo do seu turno."}, {"n": "Amalgamar", "acao": "Padrão", "desc": "Enquanto está com 0 PV, a múmia pode amalgamar um ser morto ou uma criatura de Morte adjacente. Se o fizer, ela se entrelaça com o alvo, tornando-se uma versão mais poderosa de si mesma; ela recupera 200 PV, passa a atacar três vezes com suas garras enfaixadas e seus ataques causam +5 pontos de dano cada. Uma múmia que já esteja amalgamada com outro ser pode se amalgamar mais uma vez, combinando-se com um total de dois seres. Ao se amalgamar pela segunda vez, ela recupera mais 200 PV, passa a atacar quatro vezes com suas garras enfaixadas e aumenta o bônus de dano em +5 (para um total de +10 por ataque)."}], "desc": "", "def": 35}'::jsonb),
(34,'Nidere','Morte','320',224,'{"tamanho": "Grande", "pv": 800, "desloc": 24.0, "atr": {"agi": 5, "for": 5, "int": 3, "pre": 4, "vig": 5}, "fort": 25, "refl": 25, "vont": 15, "ini": 25, "perc": 25, "pericias": [{"n": "Furtividade", "b": 23}, {"n": "Sobrevivência", "b": 20}], "resist": "Corte, impacto, perfuração e Morte 20", "vuln": "Energia", "sentidos": "Faro", "ataques": [{"n": "Garra Invertida", "alc": "Corpo a corpo x2", "teste": 35, "dano": "4d10+40 Morte"}, {"n": "Mordida Invertida", "alc": "Corpo a corpo", "teste": 35, "dano": "4d12+40 Morte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 8d6 mental NEX 95%+ é imune"}, {"n": "Caçador Veloz", "acao": "Passiva", "desc": "O nidere pode se mover em seu deslocamento normal sem penalidade em Furtividade."}, {"n": "Regeneração Acelerada", "acao": "Passiva", "desc": "O nidere possui Cura Acelerada 50. Ele perde esta habilidade se resolverem seu Enigma de Medo."}, {"n": "Senso de Direção Perfeito", "acao": "Passiva", "desc": "Nideres nunca se perdem e recebem + OO em Percepção e Sobrevivência (já contabilizados na ficha). A criatura perde esta habilidade caso seu enigma de medo seja resolvido."}, {"n": "Reverter", "acao": "Livre", "desc": "Um ser que sofra dano das garras invertidas é afetado por um surto temporal capaz de apodrecer a carne. Ele fica enjoado até o final do seu próximo turno."}, {"n": "Rastrear e Abater", "acao": "Livre", "desc": "O nidere causa +6d6 pontos de dano contra seres desprevenidos."}], "desc": "", "def": 50}'::jsonb),
(35,'O Deus da Morte','Morte','400',230,'{"tamanho": "Grande", "pv": 2000, "desloc": 15.0, "atr": {"agi": 6, "for": 6, "int": 5, "pre": 5, "vig": 7}, "fort": 35, "refl": 35, "vont": 35, "ini": 30, "perc": 30, "pericias": [], "resist": "Corte, impacto e perfuração 20", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Soco Espiral", "alc": "Corpo a corpo x2", "teste": 45, "dano": "5d10+50 Morte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 10d8 mental"}, {"n": "Ciclo Infinito", "acao": "Passiva", "desc": "O Deus da Morte recupera 50 PV no início de cada um de seus turnos. Quando é reduzido a 0 PV ou menos, ele se transforma em uma poça de Lodo. No começo do seu próximo turno, ele se manifesta no cadáver mais próximo do corpo original (ou no corpo com maior NEX a seu alcance), recuperando todos os seus PV e se curando de todas as condições. Quando seu Enigma de Medo for resolvido, ele perde a regeneração e a capacidade de se manifestar em um corpo próximo quando reduzido a 0 PV ou menos."}, {"n": "Destruir o Diabo", "acao": "Passiva", "desc": "O Deus da Morte é a única coisa capaz de causar a solução do Enigma de Medo do Diabo."}, {"n": "Potência de Morte", "acao": "Passiva", "desc": "O modificador do Deus da Morte para todos os testes de perícia baseados em Força, Vigor ou Presença é +35, e para testes baseados nos demais atributos, é +25."}, {"n": "Senhor do Tempo", "acao": "Passiva", "desc": "O Deus da Morte é um manipulador do tempo. No início de cada rodada, ele rola 1d20 e recebe um turno adicional na contagem de iniciativa correspondente ao resultado desta jogada."}, {"n": "Agarrão", "acao": "Livre", "desc": "Se o Deus da Morte acertar um ataque de soco espiral em um ser Médio ou menor, pode tentar agarrar o alvo (teste 6 O +47)."}, {"n": "Controlar Relógio Interno", "acao": "Livre", "desc": "No início de cada um de seus turnos, o Deus da Morte encerra até duas condições que o estejam afetando."}, {"n": "Controlar Mortos", "acao": "Movimento", "desc": "O Deus da Morte controla qualquer criatura de Morte em alcance longo, fazendo-as percorrer seu deslocamento e realizar um ataque."}, {"n": "Espiral Descendente", "acao": "Movimento", "desc": "O Deus da Morte acelera o tempo de um ser que esteja agarrando, mas faz com que ele sinta cada segundo passando, paralisado e sem poder agir. O ser envelhece 3d20 anos. Para cada ano envelhecido, sofre 1 ponto de dano mental."}, {"n": "Espiral Destrutiva", "acao": "Padrão", "desc": "O Deus da Morte cria uma enorme espiral de Morte com 12m de raio em alcance longo. Todos os personagens dentro da área sofrem 10d10+50 pontos de dano de Morte (Fortitude DT 45 reduz à metade)."}], "desc": "", "def": 60}'::jsonb),
(36,'Sempiternal','Morte','360',226,'{"tamanho": "Médio", "pv": 990, "desloc": 12.0, "atr": {"agi": 5, "for": 5, "int": 4, "pre": 5, "vig": 4}, "fort": 20, "refl": 30, "vont": 25, "ini": 25, "perc": 20, "pericias": [], "resist": "Corte, impacto e perfuração 20", "vuln": "Energia", "sentidos": "", "ataques": [{"n": "Dedos Alongados", "alc": "Corpo a corpo x4", "teste": 40, "dano": "4d10 Morte mais"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 40 8d8 mental"}, {"n": "Toque Acelerador", "acao": "Passiva", "desc": "Sempre que um ser sofre dano dos dedos alongados, envelhece 1d10 anos. Se a vítima envelhecer 20 anos ou mais desta forma, fica fraca até o fim da cena. Se envelhecer 40 anos ou mais, fica debilitada até o fim da cena. E se envelhecer 60 anos ou mais, morre. Seres com afinidade com a Morte são imunes a este efeito."}, {"n": "Correntes de Lodo", "acao": "Movimento", "desc": "O sempiternal projeta vinhas de Lodo pelo chão, ocupando toda a área em alcance médio. Todos os seres na área sofrem 20d6 pontos de dano de Morte (Fortitude DT 40 reduz à metade). Um ser que fique machucado devido a este dano é infectado com o Lodo e recebe vulnerabilidade a Morte até o fim da cena. Um ser reduzido a 0 PV se torna um enraizado (p. 214)."}], "desc": "", "def": 53}'::jsonb),
(37,'Succ','Morte','40',227,'{"tamanho": "Médio", "pv": 65, "desloc": 12.0, "atr": {"agi": 4, "for": 2, "int": 0, "pre": 1, "vig": 1}, "fort": 0, "refl": 10, "vont": 5, "ini": 5, "perc": 5, "pericias": [], "resist": "Corte, impacto e perfuração 5, Morte 10", "vuln": "Energia", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 0, "dano": ""}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 3d6 mental NEX 30%+ é imune"}, {"n": "Sucção", "acao": "Livre", "desc": "Se acertar um personagem com sua mordida, o succ prende seus dentes no rosto da vítima e então tira o ar de seus pulmões. O personagem deve fazer um teste de Fortitude (DT 17). Se passar, consegue se soltar. Se falhar, fica inconsciente e, no início do próximo turno do succ, será reduzido a 0 PV e ficará morrendo. Enquanto estiver prendendo um personagem dessa forma, o succ não pode realizar ações, exceto reações, e seu deslocamento é reduzido para 3m. Se o succ sofrer 10 pontos de dano ou mais na mesma rodada, solta qualquer vítima que estiver prendendo. Succ"}], "desc": "", "def": 20}'::jsonb),
(38,'Aberração de Carne','Sangue','40',182,'{"tamanho": "Grande", "pv": 70, "desloc": 9.0, "atr": {"agi": 1, "for": 3, "int": 0, "pre": 1, "vig": 3}, "fort": 10, "refl": 0, "vont": 0, "ini": 0, "perc": 5, "pericias": [], "resist": "Balístico, impacto, perfuração 5, Sangue 10", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Pancada", "alc": "Corpo a corpo x2", "teste": 10, "dano": "2d6+6 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 3d6 mental NEX 30%+ é imune"}, {"n": "Agarrão", "acao": "Reação", "desc": "Se a aberração de carne acertar um ataque de pancada, ela pode tentar agarrar o alvo (teste 3 O +12). Ela pode manter até dois personagens agarrados por vez."}, {"n": "Abocanhar", "acao": "Movimento", "desc": "A aberração de carne leva até dois personagens agarrados para dentro de sua boca central, que são abocanhados e continuam agarrados. Quando é abocanhado, e no início de cada turno da aberração em que continuar agarrado desta forma, o personagem sofre 3d6 pontos de dano de perfuração (Fortitude DT 15 reduz à metade). Qualquer personagem adjacente a aberração de carne pode gastar uma ação padrão para fazer um teste de Atletismo (DT 20) para tentar tirar outro personagem de dentro da boca."}], "desc": "", "def": 19}'::jsonb),
(39,'Aniquilação','Sangue','380',186,'{"tamanho": "Colossal", "pv": 1200, "desloc": 15.0, "atr": {"agi": 4, "for": 5, "int": 3, "pre": 4, "vig": 5}, "fort": 30, "refl": 25, "vont": 20, "ini": 20, "perc": 20, "pericias": [{"n": "Atletismo", "b": 20}], "resist": "Dano 50", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garras", "alc": "Corpo a corpo x2", "teste": 40, "dano": "4d10+30 Sangue"}, {"n": "Tentáculos Espinhentos", "alc": "Corpo a corpo x2", "teste": 40, "dano": "2d12+30 Sangue"}, {"n": "Disparo de Espinhos", "alc": "Distância x3", "teste": 40, "dano": "2d10+20 Sangue"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 9d8 mental"}, {"n": "Agarrão", "acao": "Reação", "desc": "Se a Aniquilação acertar um ataque de tentáculos espinhentos, ela pode tentar agarrar o alvo (teste 5 O +50). Ela pode manter até quatro personagens agarrados por vez."}, {"n": "Instinto Aniquilador", "acao": "Reação", "desc": "Sempre que um personagem em alcance curto da Aniquilação se movimenta mais do que 3m, a Aniquilação realiza um ataque de tentáculos espinhentos contra o personagem."}, {"n": "Apertar e Destruir", "acao": "Livre", "desc": "No início do seu turno, a Aniquilação aperta os personagens agarrados com seus tentáculos, causando 40 pontos de dano de Sangue."}, {"n": "Bater As Asas", "acao": "Movimento", "desc": "A Aniquilação bate suas asas, criando um som ensurdecedor. Cada personagem em alcance longo sofre 8d6 pontos de dano Mental, é empurrado 6m para longe da Aniquilação e fica atordoado por uma rodada (Fortitude DT 40 reduz o dano à metade e evita os efeitos)."}, {"n": "Estrangulamento Final", "acao": "Movimento", "desc": "A Aniquilação se desloca 15m enquanto seus inúmeros braços agarram e estrangulam personagens no caminho. Cada personagem que ficar adjacente a Aniquilação durante esse deslocamento fica agarrado e asfixiado (Reflexos DT 30 evita). Um personagem agarrado pode escapar gastando uma ação padrão e passando em um teste de Reflexos (DT 30)."}, {"n": "Tempestade de Espinhos", "acao": "Completa", "desc": "A Aniquilação lança todos os seus espinhos. Todos os personagens em alcance médio sofrem 20d6+20 pontos de dano de Sangue (Reflexos DT 40 reduz à metade). A Aniquilação só pode usar esta habilidade uma vez por cena e, quando a usa, perde seu disparo de espinhos até o fim da cena."}], "desc": "", "def": 58}'::jsonb),
(40,'Carente','Sangue','300',188,'{"tamanho": "Grande", "pv": 700, "desloc": 12.0, "atr": {"agi": 4, "for": 4, "int": 2, "pre": 3, "vig": 4}, "fort": 25, "refl": 25, "vont": 15, "ini": 15, "perc": 10, "pericias": [{"n": "Atletismo", "b": 20}, {"n": "Enganação", "b": 15}], "resist": "Balístico, impacto, perfuração e Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garras de Sangue", "alc": "Corpo a corpo x2", "teste": 35, "dano": "2d8+20 Sangue"}, {"n": "Ferrão de Sangue", "alc": "Corpo a corpo", "teste": 35, "dano": "2d12+20 Sangue"}, {"n": "Tentáculo", "alc": "Corpo a corpo", "teste": 35, "dano": "2d8+20 Sangue"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 7d8 mental NEX 90%+ é imune"}, {"n": "Carência", "acao": "Passiva", "desc": "Qualquer ser que já esteve envolvido na gestação de outro ser recebe + O em ataques contra o carente, porém o carente também recebe + O em ataques contra esse ser."}, {"n": "Regeneração de Sangue", "acao": "Passiva", "desc": "O carente possui Cura Acelerada 20. Se o carente ficar inconsciente ou sofrer dano de Energia, esta habilidade deixa de funcionar até o fim da cena."}, {"n": "Forma Infantil", "acao": "Movimento", "desc": "O carente se contorce de volta para o corpo da pequena criança para passar em espaços pequenos, se retraindo e expandindo quando achar necessário. Além disso, o carente não consegue abrir a primeira porta para entrar em um lugar. Uma vez que essa porta é aberta e ele deixa de estar na forma infantil, pode ignorar essa restrição."}, {"n": "Rasteira de Tentáculo", "acao": "Reação", "desc": "Uma vez por rodada, quando fica adjacente a dois ou mais seres, o carente faz um ataque de tentáculo contra um deles. Se o carente acertar o ataque, a vítima fica caída e é empurrada 6m para longe dele."}, {"n": "Sugada Mortal", "acao": "Livre", "desc": "Usando seu ferrão, o carente consegue sugar fluidos e apodrecer os órgãos internos. Um ser atingido pelo ferrão de sangue fica debilitado e enjoado até o fim da cena (Fortitude DT 35 evita)."}, {"n": "Você É Minha Mamãe?", "acao": "Movimento", "desc": "O carente usa a parte que simula o corpo de uma criança para abraçar um ser adjacente, que fica paralisado até ser solto (Reflexos DT 25 evita). O carente pode manter o abraço indefinidamente, mas será forçado a soltar o alvo se sofrer dano de Energia."}], "desc": "", "def": 40}'::jsonb),
(41,'Dama de Sangue','Sangue','60',190,'{"tamanho": "Enorme", "pv": 105, "desloc": 12.0, "atr": {"agi": 2, "for": 3, "int": 1, "pre": 2, "vig": 2}, "fort": 10, "refl": 5, "vont": 0, "ini": 0, "perc": 10, "pericias": [], "resist": "Balístico, impacto e perfuração 10, Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Tentáculo", "alc": "Corpo a corpo x2", "teste": 10, "dano": "2d6+5 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 3d6 mental NEX 35%+ é imune"}, {"n": "Consumir", "acao": "Passiva", "desc": "Quando invocada, a dama de Sangue não possui as habilidades da coluna ao lado. Sempre que consome um corpo, recebe uma das habilidades, na ordem da ficha (ou seja, ganha primeiro Arremessar, depois Chuva de Ácido e assim por diante). Para consumir um corpo, a dama de Sangue precisa estar adjacente ao cadáver e gastar uma ação padrão. No começo de seu turno, se não tiver consumido sete corpos, a dama de Sangue irá utilizar suas ações para se deslocar na direção de um corpo e consumi-lo. Assim que tiver consumido sete corpos, ela pode agir normalmente."}, {"n": "Arremessar (flor Rosa)", "acao": "Movimento", "desc": "A dama de Sangue ergue um personagem em alcance curto e o arremessa a um ponto a sua escolha também em alcance curto. O personagem sofre 2d6 pontos de dano de impacto e fica caído (Reflexos DT 15 evita todo o efeito). A flor rosa murcha se a dama de Sangue entrar em contato com fertilizante. Isso faz a dama perder esta habilidade e sofrer – O em Luta."}, {"n": "Chuva de Ácido (flor Vermelha)", "acao": "Movimento", "desc": "A dama espirra ácido que derrete carne e corrói metal. Todos os personagens em alcance curto sofrem 4d4 pontos de dano químico (Fortitude DT 15 reduz à metade). A flor vermelha murcha se a dama de Sangue entrar em contato com agrotóxico. Isso faz a dama perder esta habilidade e reduz suas resistências a dano em 5."}, {"n": "Espinhos (flor Amarela)", "acao": "Movimento", "desc": "A dama dispara espinhos em até três alvos em alcance médio. Cada alvo sofre 2d8 pontos de dano de perfuração (Reflexos DT 15 reduz à metade). A flor amarela murcha se a dama de Sangue sofrer 10 pontos de dano de fogo de um único efeito. Isso faz a dama perder esta habilidade e sofrer – O em testes de Reflexos."}, {"n": "Grito Devastador (flor Roxa)", "acao": "Movimento", "desc": "A dama emite um grito agudo que afeta a mente e causa confusão. Todos os personagens em alcance curto ficam confusos (Vontade DT 15 evita). Um personagem que falhe no teste pode repeti-lo no final do seu turno. A flor roxa murcha se a dama de Sangue entrar em contato com o bulbo de bravo purpulis , uma planta roxa que cresce em algumas pedras. Isso faz a dama perder esta habilidade e sofrer – O em testes de Vontade."}, {"n": "Miasma Fétido (flor Azul)", "acao": "Padrão", "desc": "A dama de Sangue expele um miasma fétido que contamina o ar. Todos os personagens em alcance curto ficam enjoados por 1d4+1 rodadas (Fortitude DT 15 reduz à 1 rodada). A flor azul murcha se a dama de Sangue sofrer dano de eletricidade ou Energia. Isso faz a dama perder esta habilidade e reduz seu deslocamento em 6m."}, {"n": "Prisão de Tentáculos (flor Verde)", "acao": "Padrão", "desc": "A criatura penetra o solo com seus tentáculos e escolhe um personagem em alcance curto. Esse personagem fica agarrado até que os tentáculos sejam destruídos (os tentáculos são acertados automaticamente e tem 20 PV). A flor verde murcha se for molhada em água corrente. Isso faz a dama perder esta habilidade e reduz sua Defesa em 5."}, {"n": "Visão Macabra (flor Laranja)", "acao": "Movimento", "desc": "O movimento hipnotizante da flor faz com que o personagem tenha delírios de imagens macabras e perturbadas. Todos os personagens em alcance médio sofrem 1d6 pontos de dano Mental (Vontade DT 15 reduz à metade). A flor laranja murcha se a dama de Sangue sofrer 10 pontos de dano de corte de um único efeito. Isso faz a dama perder esta habilidade e reduz seus PV totais em 20."}], "desc": "", "def": 20}'::jsonb),
(42,'Enpap-x','Sangue','180',193,'{"tamanho": "Grande", "pv": 360, "desloc": 12.0, "atr": {"agi": 2, "for": 4, "int": 1, "pre": 2, "vig": 3}, "fort": 15, "refl": 15, "vont": 10, "ini": 10, "perc": 10, "pericias": [], "resist": "Balístico, impacto e perfuração 10, Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Socão", "alc": "Corpo a corpo x4", "teste": 20, "dano": "2d10+10 impacto"}, {"n": "Correntes", "alc": "Distância x3 CURTO", "teste": 15, "dano": "2d8+10 impacto"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 25 6d6 mental NEX 60%+ é imune"}, {"n": "Transformação", "acao": "Passiva", "desc": "O enpap-X começa o combate como um existido comum, usando todas as estatísticas da ficha da página 240. Quando ele é reduzido a 0 PV, porém, em vez de morrer, se transforma: passa a usar a ficha desta página (inclusive gerando o efeito de sua presença perturbadora) e recupera todos os seus PV, ficando com 360 PV."}, {"n": "Acorrentar", "acao": "Livre", "desc": "Se o enpap-X acertar um ataque de correntes em um personagem Médio ou menor, pode tentar agarrar o alvo à distância (teste 2 O +17). No começo do seu turno, o enpap-X estrangula cada personagem agarrado desta forma, causando 4d6 pontos de dano de impacto. O enpap-X pode manter até dois personagens agarrados simultaneamente."}, {"n": "Forma Desencadeada", "acao": "Reação", "desc": "Quando faz um acerto crítico com um socão ou com uma corrente, o enpap-X pode derrubar o alvo ou empurrá-lo 3m na direção oposta ."}, {"n": "Crescer", "acao": "Reação", "desc": "Movido pelo Sangue incontrolável, o enpap-X desenvolve força conforme desfere seus golpes. Sempre que acertar um personagem com seu socão, o enpap-X recebe um bônus cumulativo de +1d6 em suas próximas rolagens de dano até o fim do turno. Ou seja, se acertar o primeiro socão, no segundo recebe +1d6 de dano. Se acertar o segundo, no terceiro recebe +2d6. E se acertar o terceiro, no quarto socão recebe +3d6."}, {"n": "Marcas do Terror", "acao": "Movimento", "desc": "O enpap-X faz com que as marcas em seu corpo brilhem com uma luz dourada, revelando as atrocidades eternizadas em sua pele. Todos os personagem em alcance curto do enpap-X sofrem 4d6 pontos de dano mental (Vontade DT 25 reduz à metade). Um personagem que passe no teste de resistência fica imune a esta habilidade até o final da cena."}], "desc": "", "def": 36}'::jsonb),
(43,'Kerberos','Sangue','340',194,'{"tamanho": "Enorme", "pv": 1150, "desloc": 18.0, "atr": {"agi": 4, "for": 5, "int": 0, "pre": 3, "vig": 5}, "fort": 25, "refl": 20, "vont": 15, "ini": 15, "perc": 20, "pericias": [{"n": "Atletismo", "b": 25}], "resist": "Balístico, impacto, perfuração e Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 40, "dano": "4d12+30 Sangue"}, {"n": "Disparo de Espinhos", "alc": "Distância", "teste": 35, "dano": "4d8+20 Sangue"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 10d6 mental NEX 99%+ é imune"}, {"n": "Ataque Flexível", "acao": "Passiva", "desc": "O kerberos é movido por sede de Sangue e desejo de matar. Ele pode executar até quatro ataques por rodada, combinando ataques corpo a corpo e à distância. Entretanto, ele nunca pode executar o mesmo ataque mais de três vezes na mesma rodada."}, {"n": "Devorar", "acao": "Livre", "desc": "Uma vez por cena, quando reduz os PV de um personagem a 0 com sua mordida, o kerberos pode devorá-lo, matando-o instantaneamente e recuperando PV iguais à metade dos PV totais da vítima. A vítima tem direito a um teste de Fortitude (DT 40) para evitar o efeito."}, {"n": "Derrubar e Devorar", "acao": "Completa", "desc": "O kerberos usa a manobra derrubar em um personagem a até 3m (teste 5 O +45). Se vencer o teste de manobra, o kerberos desfere três ataques de mordida contra o personagem. O dano destes ataques aumenta para 4d12+40."}], "desc": "", "def": 46}'::jsonb),
(44,'Minotauro','Sangue','280',197,'{"tamanho": "Grande", "pv": 750, "desloc": 12.0, "atr": {"agi": 4, "for": 5, "int": 1, "pre": 3, "vig": 5}, "fort": 20, "refl": 15, "vont": 10, "ini": 15, "perc": 20, "pericias": [{"n": "Atletismo", "b": 20}], "resist": "Balístico, impacto, perfuração e Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Chifres", "alc": "Corpo a corpo", "teste": 30, "dano": "6d12+20 perfuração"}, {"n": "Machado", "alc": "Corpo a corpo x2", "teste": 32, "dano": "4d12+20 corte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 35 8d6 mental NEX 80%+ é imune"}, {"n": "Cravar Chifres", "acao": "Livre", "desc": "Se fizer uma investida com seus chifres e acertar o ataque, o minotauro crava seus chifres no alvo, que fica agarrado. Enquanto mantém um ser agarrado dessa forma o minotauro não pode atacar com seus chifres. Porém, no final de cada turno da vítima no qual ela ainda esteja agarrada pelos chifres, ela sofre 4d12+20 pontos de dano de Sangue."}], "desc": "", "def": 44}'::jsonb),
(45,'Mulher Afogada','Sangue','140',199,'{"tamanho": "Grande", "pv": 240, "desloc": 9.0, "atr": {"agi": 4, "for": 3, "int": 2, "pre": 2, "vig": 3}, "fort": 10, "refl": 10, "vont": 5, "ini": 10, "perc": 5, "pericias": [], "resist": "Balístico, Energia, impacto e perfuração 10, Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 15, "dano": "4d8+8 perfuração"}, {"n": "Garras", "alc": "Corpo a corpo x2", "teste": 15, "dano": "4d6+6 corte"}, {"n": "Jato de Sangue", "alc": "Distância CURTO", "teste": 10, "dano": "4d8+8 Sangue"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 25 4d8 mental NEX 50%+ é imune"}, {"n": "Forma de Sangue", "acao": "Passiva", "desc": "Por padrão, a mulher afogada é encontrada na forma de líquido de Sangue. Nesta forma, ela possui resistência a balístico, corte, impacto, perfuração e Sangue 20; deslocamento 36m e pode percorrer canos, frestas e orifícios, como qualquer líquido; e recebe as habilidades Afogar em Sangue , Arrancar Sangue e Invadir Órgãos (todas as ações marcadas com o ícone ). Ela perde esta habilidade quando é invocada em sua forma física (após seu Enigma de Medo ser desvendado)."}, {"n": "Sugar Sangue", "acao": "Movimento", "desc": "A mulher afogada devora o corpo de um personagem adjacente que tenha morrido nesta cena, recuperando 40 PV no processo."}, {"n": "Afogar Em Sangue", "acao": "Padrão", "desc": "A mulher afogada invade os orifícios do nariz e da boca de um personagem em alcance curto, afogando-o com Sangue. O personagem fica asfixiado. No início de cada um de seus turnos, pode fazer um teste de Fortitude (DT 24). Se passar, encerra a condição e faz a mulher afogada ser expelida na forma líquida para um espaço adjacente."}, {"n": "Arrancar Sangue", "acao": "Reação", "desc": "Toda vez que a mulher afogada é arrancada de um corpo que ela esteja asfixiando com afogar em Sangue, ela carrega consigo parte do sangue da vítima, causando 6d6 pontos de dano de Sangue e deixando-a fraca."}, {"n": "Invadir Órgãos", "acao": "Movimento", "desc": "A mulher afogada invade órgãos vitais de um personagem que ela esteja asfixiando com afogar em Sangue. O personagem sofre 6d6 pontos de dano de Sangue e fica enjoado."}], "desc": "", "def": 28}'::jsonb),
(46,'O Diabo','Sangue','400',206,'{"tamanho": "Médio", "pv": 1666, "desloc": 18.0, "atr": {"agi": 6, "for": 6, "int": 6, "pre": 6, "vig": 6}, "fort": 35, "refl": 35, "vont": 35, "ini": 35, "perc": 25, "pericias": [], "resist": "Balístico, impacto e perfuração 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Arma Sangrenta", "alc": "Corpo a corpo x2, crítico x3", "teste": 45, "dano": "2d10+50 Sangue"}, {"n": "Chifre do Diabo", "alc": "Corpo a corpo, crítico x3", "teste": 45, "dano": "2d8+50 Sangue"}, {"n": "Arma Sangrenta", "alc": "Distância x2, crítico x3", "teste": 45, "dano": "2d10+50 Sangue"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 45 10d8 mental"}, {"n": "Ardiloso", "acao": "Passiva", "desc": "O Diabo gosta de fazer pactos e ocasionalmente aparece para pessoas normais. Ele pode escolher não ativar sua Presença Perturbadora quando encontra um personagem."}, {"n": "Decepar Máscara", "acao": "Passiva", "desc": "A intensidade dos sentimentos do Diabo é a única coisa capaz de romper a calmaria do Equilíbrio e resolver o Enigma de Medo da Máscara do Desespero."}, {"n": "Potência de Sangue", "acao": "Passiva", "desc": "O Diabo recupera 50 PV no início de cada um de seus turnos. Além disso, seu modificador para todos os testes de perícia baseados em Força, Vigor ou Presença é +35, e para testes baseados nos demais atributos, é +25."}, {"n": "Explodir Em Sangue", "acao": "Livre", "desc": "O Diabo é capaz de controlar o sangue de qualquer ser com o qual ele tenha contato direto. Se ele causar dano em um personagem usando sua arma sangrenta, ou se tocar diretamente em uma ferida de um personagem, ele causa 10d6 pontos de dano de Sangue. O Diabo pode usar esta habilidade duas vezes por turno."}, {"n": "Sangrar", "acao": "Livre", "desc": "Se o Diabo acertar um ataque com seu chifre, pode escolher soltar o apêndice e deixá-lo preso no personagem. Um personagem com um chifre preso em si sofre vulnerabilidade a Sangue até removê-lo. Fazer isso requer uma ação padrão e causa 8d8 pontos de dano de Sangue. O chifre do Diabo sempre cresce de volta no começo do seu turno."}, {"n": "Transportar Pelo Sangue", "acao": "Movimento", "desc": "O Diabo pode se movimentar através do Sangue, inclusive daquele que esteja saindo de dentro de um personagem. Com uma ação de movimento, o Diabo pode se deslocar para qualquer espaço que tenha uma grande quantidade de sangue exposta ou adjacente a um personagem machucado ou morrendo."}, {"n": "Senhor do Sangue", "acao": "Padrão", "desc": "Uma vez por cena, o Diabo pode invocar e controlar uma ou mais criaturas de Sangue cujo VD total somado seja até 400. As criaturas aparecem em alcance médio do Diabo e agem a partir da próxima rodada, no turno do Diabo, seguindo a vontade dele."}, {"n": "Pacto", "acao": "Padrão", "desc": "O Diabo oferece ao alvo um pacto de Sangue. Se o pacto for aceito, o Diabo irá cumprir o que foi prometido, normalmente com resoluções distorcidas ao pé da letra. Em troca, o alvo sofre 10d6 pontos de dano mental e, se enlouquecer como resultado, se torna um servo obcecado pelo Diabo para o resto da vida."}, {"n": "Desejos de Sangue", "acao": "Completa", "desc": "Todos os personagens em alcance médio do Diabo entram em uma fúria de Sangue e atacam outro personagem em alcance curto a escolha do Diabo (Vontade DT 45 evita). Um personagem afetado por esta habilidade deve usar sua ação com o maior potencial de dano, mas não pode conjurar rituais. Um personagem que passe no teste de Vontade fica imune a esta habilidade até final da cena."}], "desc": "", "def": 66}'::jsonb),
(47,'Titã de Sangue','Sangue','220',201,'{"tamanho": "Colossal", "pv": 550, "desloc": 12.0, "atr": {"agi": 2, "for": 5, "int": 1, "pre": 1, "vig": 4}, "fort": 15, "refl": 10, "vont": 10, "ini": 10, "perc": 15, "pericias": [], "resist": "Balístico, impacto, perfuração e Sangue 20", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida", "alc": "Corpo a corpo", "teste": 25, "dano": "4d12+10 perfuração"}, {"n": "Garras", "alc": "Corpo a corpo x2", "teste": 25, "dano": "4d8+10 corte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 30 7d6 mental NEX 70%+ é imune"}, {"n": "Sede de Sangue", "acao": "Passiva", "desc": "Os ataques do titã causam +4d6 pontos de dano de Sangue em personagens que estejam machucados ou sangrando."}, {"n": "Estraçalhar", "acao": "Livre", "desc": "Se o titã acertar um ser com sua mordida, ele estraçalha o alvo, que sofre 4d12+10 pontos de dano de perfuração e fica sangrando até final da cena (Reflexos DT 30 reduz o dano à metade e evita a condição)."}], "desc": "", "def": 35}'::jsonb),
(48,'Zumbi de Sangue','Sangue','20',202,'{"tamanho": "Médio", "pv": 45, "desloc": 9.0, "atr": {"agi": 2, "for": 2, "int": 0, "pre": 1, "vig": 2}, "fort": 5, "refl": 5, "vont": 5, "ini": 5, "perc": 10, "pericias": [], "resist": "Balístico, impacto e perfuração 5, Sangue 10", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Garras", "alc": "Corpo a corpo x2", "teste": 5, "dano": "1d6+5 corte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 15 2d6 mental NEX 25%+ é imune"}], "desc": "", "def": 17}'::jsonb),
(49,'Zumbi de Sangue Bestial','Sangue','100',203,'{"tamanho": "Grande", "pv": 200, "desloc": 12.0, "atr": {"agi": 2, "for": 3, "int": 0, "pre": 2, "vig": 3}, "fort": 10, "refl": 5, "vont": 5, "ini": 15, "perc": 10, "pericias": [{"n": "Furtividade", "b": 13}], "resist": "Balístico, impacto e perfuração 5, Sangue 10", "vuln": "Morte", "sentidos": "Percepção às cegas", "ataques": [{"n": "Mordida de Sangue", "alc": "Corpo a corpo", "teste": 15, "dano": "2d10+5 perfuração"}, {"n": "Garras de Sangue", "alc": "Corpo a corpo x2", "teste": 15, "dano": "2d6+5 corte"}], "habilidades": [{"n": "Presença Perturbadora", "acao": "Passiva", "desc": "DT 20 4d6 mental NEX 45%+ é imune"}, {"n": "Furtivo e Letal", "acao": "Passiva", "desc": "Quando ataca um personagem desprevenido, o zumbi de Sangue bestial recebe + O nos testes de ataque e, se acertar, cada ataque causa dois dados de dano adicional do mesmo tipo."}, {"n": "Instinto Predatório", "acao": "Passiva", "desc": "O zumbi de Sangue bestial não sofre penalidade em Furtividade por se mover seu deslocamento normal."}], "desc": "", "def": 23}'::jsonb)
